# Generated by `cargo xtask formula` in https://github.com/michel-onstein/acs for each release
# (scripts/update-tap.sh): edit the generator there, not this file.
#
# acs releases are signed; SHA256SUMS.sig is checked against this key:
#   ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAILbxQW5C9X7CdwcQ4bab0gsQi4Evk2xfgmI/972dlHCb acs release signing
# Verify a release by hand:
#   printf 'releases@acs namespaces="acs-release" %s\n' "$key" > allowed
#   ssh-keygen -Y verify -f allowed -I releases@acs -n acs-release -s SHA256SUMS.sig < SHA256SUMS
class Acs < Formula
  desc "Persistent, reconnecting remote shells over ssh"
  homepage "https://github.com/michel-onstein/acs"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.17.0/acs-0.17.0-aarch64-apple-darwin.tar.gz"
      sha256 "4d15bc75e9bc8fc9e9360ca1b1b0f80d600130ed18a2ea0594d43e4cf2946083"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.17.0/acs-0.17.0-x86_64-apple-darwin.tar.gz"
      sha256 "36dff76d3290877eab93cb874d829bd7bbef2d6b3f61120406284a503b948a48"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/michel-onstein/acs/releases/download/v0.17.0/acs-0.17.0-aarch64-unknown-linux-musl.tar.gz"
      sha256 "5e7792518c4c6c486f14e35108915df2241acd307fa4d5e05598dd9471404ae4"
    end

    on_intel do
      url "https://github.com/michel-onstein/acs/releases/download/v0.17.0/acs-0.17.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "16261dcde83963e18eb10d8f75f4e6f170796033494b743a1d8d84f15b8bc01e"
    end
  end

  def install
    bin.install "acs"
  end

  test do
    out = shell_output("#{bin}/acs --version")
    assert_match "acs #{version} ", out
    remotes = out[/^installs remotes: (.*)$/, 1].to_s.split(", ")
    assert_includes remotes, "x86_64-unknown-linux-musl"
    assert_includes remotes, "aarch64-unknown-linux-musl"
  end
end
